<script setup lang="ts">
import {ref,watch} from 'vue'
import {api,type ReminderConfig} from '../services/api'
const props=defineProps<{workspaceId:string}>(),emit=defineEmits<{saved:[]}>()
const config=ref<ReminderConfig>(),error=ref(''),busy=ref(false),message=ref('');let sequence=0
watch(()=>props.workspaceId,async id=>{const token=++sequence;config.value=undefined;error.value='';message.value='';if(!id)return;try{const value=await api.GetReminderConfig(id);if(token===sequence)config.value=value}catch(e){if(token===sequence)error.value=String(e)}},{immediate:true})
async function save(){if(!config.value)return;const id=props.workspaceId,token=sequence;busy.value=true;error.value='';message.value='';try{const saved=await api.SaveReminderConfig(id,{...config.value});if(token===sequence){config.value=saved;message.value='提醒设置已保存';emit('saved')}}catch(e){if(token===sequence)error.value=String(e)}finally{busy.value=false}}
</script>
<template><section aria-label="任务提醒设置"><p>每天按指定时间提醒当前工作区中未完成的到期任务，候选任务需先确认。</p><p class="field-help">提醒在应用运行时生效；关闭应用期间不会发送系统通知，重新打开后会检查到期任务。</p><template v-if="config"><label class="setting-row"><span><strong>启用到期提醒</strong><p>到期或逾期任务可今日忽略，也可稍后提醒。</p></span><input v-model="config.enabled" type="checkbox" aria-label="启用到期提醒" :disabled="busy"/></label><label class="field-label" for="reminder-time">每天提醒时间（本地时间）</label><input id="reminder-time" v-model="config.time" class="date-input" type="time" aria-label="每天提醒时间" :disabled="busy"/><label class="field-label" for="reminder-lead">提前提醒</label><select id="reminder-lead" v-model.number="config.leadDays" class="date-input" aria-label="提前提醒天数" :disabled="busy"><option v-for="n in 8" :key="n" :value="n-1">{{n===1?'到期当天':`提前 ${n-1} 天`}}</option></select><p class="field-help">完成任务后停止提醒；修改截止日期会生成新的提醒。设置、今日忽略和稍后提醒状态均随原生备份保存。</p><button class="primary-button" :disabled="busy||!config.time" @click="save">{{busy?'正在保存…':'保存提醒设置'}}</button></template><p v-else-if="!workspaceId" class="muted">请先打开工作区。</p><p v-if="error" class="bookmark-error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p></section></template>
